//! Generation of the self-contained Lean source for a `det3` obligation.
//!
//! The generator is a pure string builder with a fixed skeleton. Dynamic data
//! enters at exactly one place — the integer literals of the named example
//! theorem statement — and even there it is re-rendered from `i64` values, never
//! copied from the request text. That is why a request containing Lean syntax
//! cannot inject anything: by the time the generator runs, the payload is an
//! array of integers.
//!
//! The generated file is:
//!
//! ```text
//! /- header -/
//! def det3 (a b c d e f g h i : Int) : Int := ...
//!
//! theorem det3_example : det3 1 2 3 4 5 6 7 8 10 = -3 := by decide
//!
//! #print axioms det3_example
//! ```
//!
//! and it is deliberately free of `native_decide`, `#eval`, `sorry`, `axiom`,
//! `implemented_by`, `extern`, `partial` and `attribute`/`@[`. The only
//! occurrence of the substring `axiom` is the `#print axioms` command itself,
//! which is the observation being consumed, not a smuggling channel.
//!
//! The multi-term subtraction is spelled `a - b - c` rather than
//! `+ - b + - c`: both mean the same thing to Lean, but the first keeps the
//! generated file readable to humans, who are the ones reviewing it.

/// Name of the generated theorem. The literal table in
/// [`crate::axioms`] covers exactly the two names Lean prints for a `decide`
/// proof of a `Prop`-valued closed goal.
pub const EXAMPLE_THEOREM: &str = "det3_example";

/// Name of the generated definition.
pub const DET3_DEF: &str = "det3";

/// Render a single integer as a Lean `Int` literal.
///
/// Lean writes negative literals as `(-3)` in term position; using the
/// parenthesised form unconditionally for negative values keeps the generated
/// source readable and unambiguous when substituted into an application.
pub fn int_literal(v: i64) -> String {
    if v < 0 {
        format!("({v})")
    } else {
        v.to_string()
    }
}

/// The Sarrus expansion of the determinant, expanded so that `decide` only has
/// to evaluate ring operations on `Int`.
///
/// Written out explicitly (rather than as a nested sum) because it is the
/// clearest form to read and to diff against the oracle's independent spelling.
fn det3_body() -> String {
    // Rows are (a b c), (d e f), (g h i); the Sarrus expansion with signs is
    //   a*e*i + b*f*g + c*d*h - c*e*g - b*d*i - a*f*h
    "a * e * i + b * f * g + c * d * h - c * e * g - b * d * i - a * f * h".to_string()
}

/// Build the complete Lean source for one example theorem.
///
/// `values` are the matrix entries whose determinant the theorem talks about
/// (they are also what the oracle computes); `literals` are what actually gets
/// written into the statement; `rhs` is the right-hand side. Callers normally
/// pass `literals == values` and `rhs` computed from `values`; passing them
/// separately exists so that a test can build a deliberately false statement.
pub fn generate_det3_source(values: &[i64; 9], literals: &[i64; 9], rhs: i128) -> String {
    let _ = values; // the definition is generic; only the example is specialised
    debug_assert_eq!(literals.len(), 9, "det3 takes nine arguments");
    let args: Vec<String> = literals.iter().copied().map(int_literal).collect();

    let mut s = String::new();
    s.push_str("/-\n");
    s.push_str("  Self-contained proof obligation generated by himari-lean.\n");
    s.push_str("  No imports, no axioms, no `native_decide`: the goal is closed and\n");
    s.push_str("  discharged by the kernel through `by decide`.\n");
    s.push_str("-/\n\n");
    s.push_str(
        "/-- Determinant of the 3x3 integer matrix `[[a, b, c], [d, e, f], [g, h, i]]`,\n\
         computed with the Sarrus expansion. -/\n",
    );
    s.push_str(&format!(
        "def {DET3_DEF} (a b c d e f g h i : Int) : Int :=\n  {}\n\n",
        det3_body()
    ));
    s.push_str("/-- Worked example: the determinant of a specific integer matrix. -/\n");
    s.push_str(&format!(
        "theorem {EXAMPLE_THEOREM} : {DET3_DEF} {} = {} := by decide\n\n",
        args.join(" "),
        rhs
    ));
    s.push_str(&format!("#print axioms {EXAMPLE_THEOREM}\n"));
    s
}

/// The documented example from the milestone description, used by tests and by
/// the README-level smoke check.
pub const MILESTONE_VALUES: [i64; 9] = [1, 2, 3, 4, 5, 6, 7, 8, 10];

/// The determinant of [`MILESTONE_VALUES`].
///
/// Worth stating plainly: this matrix has determinant **-3**, not -306. The two
/// figures come from matrices that differ in a single entry — replacing the last
/// 10 with 9 makes the matrix singular — so the constant is pinned here and
/// checked by the oracle's own tests rather than assumed.
pub const MILESTONE_DET: i128 = -3;

#[cfg(test)]
mod tests {
    use super::*;

    fn milestone_source() -> String {
        generate_det3_source(&MILESTONE_VALUES, &MILESTONE_VALUES, MILESTONE_DET)
    }

    #[test]
    fn milestone_source_has_the_expected_shape() {
        let src = milestone_source();
        assert!(src.contains("def det3 (a b c d e f g h i : Int) : Int :="));
        assert!(
            src.contains("theorem det3_example : det3 1 2 3 4 5 6 7 8 10 = -3 := by decide"),
            "{src}"
        );
        assert!(src.contains("#print axioms det3_example"));
        assert!(src.ends_with('\n'));
    }

    /// The full expected file for the milestone request, byte for byte.
    #[test]
    fn milestone_source_is_stable() {
        let want = "/-\n  Self-contained proof obligation generated by himari-lean.\n  No imports, no axioms, no `native_decide`: the goal is closed and\n  discharged by the kernel through `by decide`.\n-/\n\n/-- Determinant of the 3x3 integer matrix `[[a, b, c], [d, e, f], [g, h, i]]`,\ncomputed with the Sarrus expansion. -/\ndef det3 (a b c d e f g h i : Int) : Int :=\n  a * e * i + b * f * g + c * d * h - c * e * g - b * d * i - a * f * h\n\n/-- Worked example: the determinant of a specific integer matrix. -/\ntheorem det3_example : det3 1 2 3 4 5 6 7 8 10 = -3 := by decide\n\n#print axioms det3_example\n";
        assert_eq!(milestone_source(), want);
    }

    #[test]
    fn negative_literals_are_parenthesised() {
        assert_eq!(int_literal(-7), "(-7)");
        assert_eq!(int_literal(0), "0");
        assert_eq!(int_literal(7), "7");
        let m = [-1, 2, 3, 4, 5, 6, 7, 8, 10];
        let src = generate_det3_source(&m, &m, -1);
        assert!(src.contains("det3 (-1) 2 3 4 5 6 7 8 10 = -1 := by decide"));
    }

    #[test]
    fn generated_source_is_free_of_forbidden_constructs() {
        let src = milestone_source();
        // The header block mentions constructs in prose ("no `native_decide`"),
        // so the assertions run on the code region only: everything after it.
        let code = src.split("-/\n\n").nth(1).expect("code follows the header");
        let code_lower = code.to_ascii_lowercase();
        for tok in [
            "native_decide",
            "#eval",
            "sorry",
            "axiom",
            "implemented_by",
            "extern",
            "partial",
            "import",
            "unsafe",
            "@[",
            "attribute",
        ] {
            // `#print axioms` is the one allowed occurrence of the word `axiom`.
            let occurrences = code_lower.matches(tok).count();
            let allowed = usize::from(tok == "axiom"); // `#print axioms`
            assert_eq!(
                occurrences, allowed,
                "token `{tok}` appears {occurrences} times in the generated code"
            );
        }
        // `by decide` must be present and be the only tactic.
        assert!(code.contains(":= by decide"));
        assert_eq!(code.matches("by ").count(), 1, "exactly one tactic: decide");
        // The only `#`-command is the axioms query.
        assert_eq!(code.matches('#').count(), 1, "only `#print axioms`");
        assert!(code.contains("#print axioms det3_example"));
    }

    #[test]
    fn code_region_contains_no_request_text_verbatim() {
        // Whatever the caller passes as an integer array, the emitted source is
        // identical in structure; only digit runs differ.
        let a = generate_det3_source(&[1; 9], &[1; 9], 4);
        let b = generate_det3_source(
            &[-9, 8, 7, 6, 5, 4, 3, 2, 1],
            &[-9, 8, 7, 6, 5, 4, 3, 2, 1],
            4,
        );
        let strip = |s: &str| -> String {
            s.chars()
                .filter(|c| !c.is_ascii_digit() && *c != '-' && *c != '(' && *c != ')')
                .collect()
        };
        assert_eq!(strip(&a), strip(&b));
    }

    #[test]
    fn example_theorem_name_matches_the_axiom_table() {
        assert_eq!(EXAMPLE_THEOREM, "det3_example");
        assert!(crate::axioms::parse_axioms(&format!(
            "'{EXAMPLE_THEOREM}' depends on axioms: [propext, Classical.choice, Quot.sound]\n"
        ))
        .is_ok());
    }
}
